        margin-bottom: 0.5;
    }

    #events-content {
        color: $text-muted;
        min-height: 3;
        padding: 1;
        border: round $secondary;
        background: $surface-darken-2;
        overflow-y: auto;
    }

    /* Idle state styling */
    #idle-message {
        text-align: center;
        color: $text-muted;
        width: 100%;
        padding: 3;
    }
    """

    def __init__(self):
        super().__init__()
        self._flow_name = "unknown"
        self._issue_number = None
        self._current_phase = ""
        self._all_phases: list[str] = []
        self._elapsed_seconds = 0.0
        self._model_info = None
        self._tool_calls: list[dict] = []
        self._timer_updated = False

    def compose(self):
        """Create child widgets for the live monitor panel."""
        yield Label("[bold cyan]Pipeline Monitor[/]", id="flow-name")
        yield Static("", id="issue-number")
        yield Static("", id="elapsed-timer")
        yield Static("", id="phase-diagram")
        yield Static("", id="model-info")
        yield Label("[bold blue]Recent Activity[/]", id="events-title")
        yield Static("", id="events-content")

    def _format_elapsed(self, seconds: float) -> str:
        """Format elapsed seconds into a human-readable string.

        Args:
            seconds: Elapsed time in seconds (float).

        Returns:
            Formatted string like "02:34" or "15:07".
        """
        mins = int(seconds // 60)
        secs = int(seconds % 60)
        return f"{mins:02d}:{secs:02d}"

    def _build_phase_diagram(self, current_phase: str, all_phases: list[str]) -> str:
        """Build a Unicode phase diagram with the current phase highlighted.

        Uses box-drawing characters to connect phases and 🔄 emoji for the
        active one.

        Args:
            current_phase: The name of the currently running phase.
            all_phases: Ordered list of all phase names in the flow.

        Returns:
            Unicode string rendering the phase diagram.
        """
        if not all_phases or not current_phase:
            return "No phases defined"

        segments = []
        for i, phase in enumerate(all_phases):
            is_current = phase == current_phase
            marker = "[bold green]🔄[/]" if is_current else "○"
            label = f"[bold]{phase}[/]" if is_current else phase
            segment = f"{marker} {label}"

            # Add connector between phases (except after last)
            if i < len(all_phases) - 1:
                next_phase = all_phases[i + 1]
                if next_phase == current_phase:
                    connector = " [bold green]→[/]"
                else:
                    connector = " → "
                segment += connector

            segments.append(segment)

        return " ".join(segments)

    def _render_idle(self):
        """Render the idle state display."""
        flow_label = self.query_one("#flow-name", Label)
        issue_label = self.query_one("#issue-number", Static)
        timer_label = self.query_one("#elapsed-timer", Static)
        phase_display = self.query_one("#phase-diagram", Static)
        model_display = self.query_one("#model-info", Static)
        events_display = self.query_one("#events-content", Static)

        flow_label.update("[bold cyan]Pipeline Monitor[/]")
        issue_label.update("")
        timer_label.update("")
        phase_display.update("Idle — no active pipeline")
        model_display.update("")
        events_display.update("")

    def update_pipeline_status(
        self,
        session_data: dict | None = None,
        progress_data: dict | None = None,
        flow_phases: list[str] | None = None,
    ):
        """Update the panel with live pipeline data from DashboardAPI.

        This is the main entry point called by the dashboard on each poll cycle.

        Args:
            session_data: Dict from get_active_session() containing active/
                         state, issue, flow, phase, elapsed_seconds, etc.
            progress_data: Dict from get_session_progress() containing model,
                          recent_events, and tool_calls.
            flow_phases: Ordered list of all phase names for the current flow
                        (from flow config), used to build the full diagram.
        """
        # Check if pipeline is idle
        is_idle = not session_data or not session_data.get("active", False)

        if is_idle:
            self._render_idle()
            return

        # Extract session metadata
        issue_num = session_data.get("issue")
        flow_name = session_data.get("flow", "unknown")
        current_phase = session_data.get("phase", "")
        elapsed_seconds = session_data.get("elapsed_seconds", 0.0)

        # Store for timer updates
        self._flow_name = flow_name
        self._issue_number = issue_num
        self._current_phase = current_phase
        self._all_phases = flow_phases or []
        self._elapsed_seconds = elapsed_seconds

        # Update header
        flow_label = self.query_one("#flow-name", Label)
        if issue_num:
            flow_label.update(f"[bold cyan]{flow_name}[/] [dim]| Issue #{issue_num}[/]")
        else:
            flow_label.update(f"[bold cyan]{flow_name}[/]")

        # Update elapsed timer
        timer_label = self.query_one("#elapsed-timer", Static)
        formatted_time = self._format_elapsed(elapsed_seconds)
        state = session_data.get("state", "running")
        state_icon = "[bold green]●[/]" if state == "running" else "◐"
        timer_label.update(
            f"{state_icon} Elapsed: [bold]{formatted_time}[/]"
        )

        # Update phase diagram
        phase_display = self.query_one("#phase-diagram", Static)
        phases_to_show = flow_phases if flow_phases else current_phase.split(",")
        phase_diagram_str = self._build_phase_diagram(current_phase, phases_to_show)
        phase_display.update(phase_diagram_str)

        # Update model info from progress data
        model_display = self.query_one("#model-info", Static)
        if progress_data and progress_data.get("model"):
            model_name = progress_data["model"]
            model_display.update(f"🤖 Model: [dim]{model_name}[/]")
        else:
            model_display.update("")

        # Update recent tool call events from progress data
        events_display = self.query_one("#events-content", Static)
        if progress_data and progress_data.get("tool_calls"):
            self._tool_calls = progress_data["tool_calls"]
            event_lines = []
            for tc in self._tool_calls[-3:]:  # Show last 3 tool calls
                status_icon = "✅" if tc.get("status") == "success" else "❌"
                tool_name = tc.get("tool", "?")
                path = tc.get("path", "?")
                event_lines.append(f"{status_icon} {tool_name}: {path}")

            if not event_lines:
                # Fallback to recent_events if no filtered tool_calls
                recent = progress_data.get("recent_events", [])
                for evt in recent[-3:]:
                    if isinstance(evt, dict) and "text" in evt:
                        text_preview = evt["text"][:80]
                        event_lines.append(f"💬 {text_preview}")

            events_display.update("\n".join(event_lines))
        else:
            events_display.update("[dim]Waiting for activity...[/]")

    def update_timer(self):
        """Increment and display the elapsed timer.

        Called periodically (every second) while a pipeline is active to
        keep the timer counting up in real time without re-polling the API.
        """
        if not self._flow_name or self._flow_name == "unknown":
            return

        self._elapsed_seconds += 1.0
        formatted_time = self._format_elapsed(self._elapsed_seconds)
        last_session = getattr(self, "_last_session", {})
        state = last_session.get("state", "running") if last_session else "running"
        state_icon = "[bold green]●[/]" if state == "running" else "◐"

        timer_label = self.query_one("#elapsed-timer", Static)
        timer_label.update(
            f"{state_icon} Elapsed: [bold]{formatted_time}[/]"
        )

    def set_last_session(self, session_data: dict):
        """Store the last known session data for timer state tracking.

        Args:
            session_data: The most recent session data dict from API.
        """
        self._last_session = session_data

    def update_logs(self, message: str):
        """No-op stub. Replaced by real-time panel updates via
        ``update_pipeline_status()``."""
        pass

#!/usr/bin/env python3
"""
SharedDetailView — Dynamic detail view widget for issues and sessions.

Replaces the old embedded drawers from IssuesPanel and SessionBrowserPanel.
Renders metadata, logs, file operations, and error summaries in a clean layout.

Usage:
    from panels.shared_detail_view import SharedDetailView

    view = SharedDetailView()
    view.populate(issue_data)   # Renders issue detail
    view.populate(session_data) # Renders session detail
"""

from textual.widgets import Static


class SharedDetailView(Static):
    """Detail view widget that renders either an Issue or a Session.

    Detects the item type from ``item_data`` and renders the appropriate
    metadata section. Handles empty states gracefully with a placeholder
    message.
    """

    CSS = """
    SharedDetailView {
        width: 100%;
        /* Height controlled by parent layout (#shared-detail in dashboard) */
        background: $surface-darken-1;
        padding: 1 2;
        overflow-y: auto;
    }

    /* ── Section headers ─────────────────────────────────────────────── */
    .detail-section {
        margin-bottom: 1;
        border-left: double $primary;
        padding-left: 1;
    }

    .section-title {
        text-align: left;
        width: 100%;
        color: $text-muted;
        dock: top;
        margin-bottom: 0.5;
    }

    /* ── Empty state ─────────────────────────────────────────────────── */
    #empty-state {
        text-align: center;
        color: $text-muted;
        padding: 4;
        height: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
    }

    #empty-state .icon {
        font-size: 3;
        margin-bottom: 1;
    }

    /* ── Issue-specific styling ──────────────────────────────────────── */
    #issue-title {
        color: $text;
        width: 100%;
        text-align: left;
        margin-bottom: 0.5;
    }

    .label-badge {
        background: $boost;
        color: $text;
        padding: 0 1;
        margin-right: 0.5;
        margin-bottom: 0.25;
        height: auto;
    }

    #issue-body {
        width: 100%;
        color: $text;
        text-align: left;
        margin-top: 0.5;
    }

    /* ── Session-specific styling ────────────────────────────────────── */
    .meta-row {
        width: 100%;
        margin-bottom: 0.25;
    }

    .meta-key {
        color: $text-muted;
        width: auto;
    }

    .meta-value {
        color: $text;
        width: auto;
    }

    /* ── File operations timeline ────────────────────────────────────── */
    #file-ops-timeline {
        width: 100%;
        margin-top: 0.5;
    }

    .op-entry {
        color: $text;
        padding-left: 1;
        height: auto;
    }

    /* ── Errors section ──────────────────────────────────────────────── */
    #errors-section {
        width: 100%;
        margin-top: 0.5;
    }

    .error-entry {
        color: $warning;
        padding-left: 1;
        height: auto;
    }

    /* ── Loading state ───────────────────────────────────────────────── */
    #loading-state {
        text-align: center;
        color: $text-muted;
        padding: 4;
        display: flex;
        align-items: center;
        justify-content: center;
        width: 100%;
        height: 100%;
    }
    """

    # ── Public API ───────────────────────────────────────────────────────

    def populate(self, item_data: dict) -> None:
        """Populate the detail view with an Issue or Session.

        Detects the type from ``item_data`` and renders the appropriate
        metadata sections.

        Args:
            item_data: A dict representing either:
                - An **Issue** (keys: number, title, body, labels,
                  created_at, state, assignee).
                - A **Session** (keys: flow, phase, model, duration_seconds,
                  file_ops_count, error_count, timestamp_str, verdict_status,
                  raw_path).

        Examples:
            >>> view.populate({
            ...     "type": "issue",
            ...     "number": 42,
            ...     "title": "Fix login bug",
            ...     "body": "Users can't log in...",
            ...     "labels": ["bug", "critical"],
            ... })

            >>> view.populate({
            ...     "type": "session",
            ...     "flow": "builder-reviewer",
            ...     "phase": "builder",
            ...     "model": "qwen-27b",
            ...     "duration_seconds": 180.5,
            ... })
        """
        # Clear current content
        self.remove_children()

        item_type = item_data.get("type", "")

        if not item_data:
            self._render_empty_state()
            return

        if item_type == "issue":
            self._render_issue(item_data)
        elif item_type == "session":
            self._render_session(item_data)
        else:
            # Unknown type — fall back to empty state with a hint
            self._render_empty_state(hint=f"Unknown item type: {item_type!r}")

    def clear(self) -> None:
        """Clear the detail view and return to the empty state."""
        self.remove_children()
        self._render_empty_state()

    # ── Rendering helpers ────────────────────────────────────────────────

    def _render_empty_state(self, hint: str = "") -> None:
        """Render the placeholder when no item is selected.

        Args:
            hint: Optional extra text shown below the default message.
        """
        self.mount(Static(
            f"[dim]Select an item to view details[/]\n\n"
            f"Click on a row in Issues or Sessions to see details here.",
            id="empty-state",
        ))

    def _render_issue(self, data: dict) -> None:
        """Render issue detail sections.

        Args:
            data: Issue dict with keys like number, title, body, labels,
                  created_at, state, assignee.
        """
        # ── Title row ─────────────────────────────────────────────────────
        issue_num = data.get("number", "?")
        title = data.get("title", "Untitled Issue")

        self.mount(Static(
            f"[bold cyan]#{issue_num}[/] {title}",
            id="issue-title",
            classes="detail-section",
        ))

        # ── Status / assignee / created row ───────────────────────────────
        status = data.get("state", "open").capitalize()
        assignee = data.get("assignee", "")
        created_at = self._format_timestamp(data.get("created_at", ""))

        meta_parts: list[str] = [f"Status: **[bold]{status}[/]**"]
        if assignee:
            meta_parts.append(f"Assignee: {assignee}")
        if created_at:
            meta_parts.append(f"Created: {created_at}")

        self.mount(Static(
            f"[dim]{' | '.join(meta_parts)}[/]",
            id="issue-meta",
        ))

        # ── Labels row ────────────────────────────────────────────────────
        labels = data.get("labels", []) or []
        if isinstance(labels, list) and labels:
            label_spans = " ".join(
                f"[bold]#{label}[/]" for label in labels[:10]
            )
            self.mount(Static(label_spans, id="issue-labels"))

        # ── Body (truncated) ─────────────────────────────────────────────
        body = data.get("body", "") or ""
        if body:
            preview = body[:500] + ("..." if len(body) > 500 else "")
            self.mount(Static(
                f"[dim]{preview}[/]",
                classes="detail-section",
                id="issue-body",
            ))

    def _render_session(self, data: dict) -> None:
        """Render session detail sections.

        Args:
            data: Session dict with keys like flow, phase, model,
                  duration_seconds, file_ops_count, error_count,
                  timestamp_str, verdict_status.  Also accepts enriched
                  dicts containing parsed ``file_operations`` and ``errors``
                  lists from session_reader.
        """
        # ── Metadata section ──────────────────────────────────────────────
        meta_lines = []

        issue_num = data.get("issue")
        if issue_num:
            meta_lines.append(f"[dim]Issue:[/] [bold cyan]#{issue_num}[/]")

        if data.get("flow"):
            meta_lines.append(
                f"[dim]Flow:[/] [bold]{data['flow']}[/]"
            )
        if data.get("phase"):
            meta_lines.append(
                f"[dim]Phase:[/] {data['phase']}"
            )
        if data.get("model"):
            model_str = str(data["model"])[:60]
            meta_lines.append(f"[dim]Model:[/] {model_str}")

        duration = self._format_duration(data.get("duration_seconds", 0))
        meta_lines.append(f"[dim]Duration:[/] {duration}")

        verdict = data.get("verdict_status")
        if verdict:
            icon_map = {"approved": "✅", "rejected": "❌", "error": "⚠️"}
            icon = icon_map.get(verdict, "➖")
            meta_lines.append(f"[dim]Verdict:[/] {icon} **{verdict}**")

        timestamp = self._format_timestamp(data.get("timestamp_str", ""))
        if timestamp:
            meta_lines.append(f"[dim]Timestamp:[/] {timestamp}")

        raw_path = data.get("raw_path", "")
        if raw_path:
            # Truncate long paths for display
            short_path = raw_path
            if len(short_path) > 80:
                short_path = "..." + short_path[-75:]
            meta_lines.append(f"[dim]Log path:[/] `{short_path}`")

        self.mount(Static("\n".join(meta_lines), id="session-meta"))

        # ── File operations timeline ──────────────────────────────────────
        file_ops = data.get("file_operations", [])
        if file_ops:
            lines = ["[bold]📋 File Operations[/]"]
            for op in file_ops[:30]:  # Cap at 30 entries
                status_icon = "✅" if op.get("status") == "success" else "❌"
                tool = (op.get("tool", "?") or "?").upper()
                path = op.get("path", "unknown")
                lines.append(f"  {status_icon} [{tool}] {path}")
            if len(file_ops) > 30:
                lines.append(f"  [dim]... and {len(file_ops) - 30} more[/]")
            self.mount(Static("\n".join(lines), classes="detail-section", id="file-ops-timeline"))
        else:
            ops_count = data.get("file_ops_count", 0)
            if ops_count > 0:
                self.mount(Static(
                    f"[bold]File Operations:[/] {ops_count}",
                    classes="detail-section",
                    id="file-ops-summary",
                ))
            else:
                self.mount(Static("[dim]No file operations recorded.[/]", id="file-ops-empty"))

        # ── Errors section ────────────────────────────────────────────────
        errors = data.get("errors", [])
        if errors:
            lines = ["[bold red]⚠️ Errors[/]"]
            for err in errors[:15]:  # Cap at 15 entries
                err_type = err.get("type", "unknown") or "unknown"
                msg = (err.get("message", "") or "")[:120]
                lines.append(f"  - [{err_type}] {msg}")
            if len(errors) > 15:
                lines.append(f"  [dim]... and {len(errors) - 15} more[/]")
            self.mount(Static("\n".join(lines), classes="detail-section", id="errors-section"))
        else:
            err_count = data.get("error_count", 0)
            if err_count > 0:
                self.mount(Static(
                    f"[bold warning]Errors:[/] {err_count}",
                    classes="detail-section",
                    id="errors-summary",
                ))
            else:
                self.mount(Static("[dim]No errors recorded.[/]", id="errors-empty"))

    # ── Formatting utilities ─────────────────────────────────────────────

    @staticmethod
    def _format_duration(seconds: float) -> str:
        """Format seconds into a human-readable duration string.

        Args:
            seconds: Duration in seconds.

        Returns:
            Formatted string like "2m 30s" or "1h 5m".
        """
        if not seconds:
            return "?"
        mins = int(seconds) // 60
        secs = int(seconds) % 60
        if mins >= 60:
            hours = mins // 60
            remaining_mins = mins % 60
            return f"{hours}h {remaining_mins}m"
        elif mins > 0:
            return f"{mins}m {secs}s"
        else:
            return f"{secs}s"

    @staticmethod
    def _format_timestamp(ts_str: str) -> str:
        """Format an ISO timestamp string into a human-readable form.

        Args:
            ts_str: ISO 8601 timestamp (e.g., '2025-05-27T10:30:00Z').

        Returns:
            Human-readable date/time or empty string if invalid.
        """
        from datetime import datetime, timezone

        if not ts_str:
            return ""

        try:
            # Handle both Z and +00:00 suffixes
            cleaned = ts_str.replace("Z", "+00:00")
            dt = datetime.fromisoformat(cleaned)
            now = datetime.now(timezone.utc)
            delta = now - dt

            total_seconds = int(delta.total_seconds())

            if total_seconds < 60:
                return f"{total_seconds}s ago"
            elif total_seconds < 3600:
                minutes = total_seconds // 60
                return f"{minutes}m ago"
            elif total_seconds < 86400:
                hours = total_seconds // 3600
                return f"{hours}h ago"
            elif total_seconds < 604800:
                days = total_seconds // 86400
                return f"{days}d ago"
            else:
                # Older than a week — show the date
                return dt.strftime("%Y-%m-%d")
        except (ValueError, TypeError):
            return ts_str if len(ts_str) <= 16 else ""

#!/usr/bin/env python3
"""
OrchestratorControls — Pipeline execution control buttons for Maestro Dashboard.

Shows:
  - Start (▶), Stop (⏹), and Pause (⏸) buttons in a horizontal row
  - Button press events are captured and dispatched to the parent dashboard

Pure UI panel — no direct I/O. All data comes through dashboard callbacks.
"""

from textual.widgets import Button, Label
from textual.containers import Horizontal


class OrchestratorControls(Horizontal):
    """Horizontal button row for pipeline execution control."""

    CSS = """
    #orchestrator-controls {
        layout: horizontal;
        align-horizontal: center;
        height: auto;
    }

    Button#btn-start-pipeline {
        width: auto;
        min-width: 24;
        margin-right: 0.5;
    }

    Button#btn-stop-pipeline {
        width: auto;
        min-width: 24;
        margin-left: 0.5;
        margin-right: 0.5;
    }

    Button#btn-pause-resume {
        width: auto;
        min-width: 24;
        margin-left: 0.5;
    }

    /* Label above the buttons */
    #controls-label {
        text-align: center;
        color: $text-accent;
        width: 100%;
        padding-bottom: 0.5;
    }
    """

    def __init__(self):
        super().__init__()
        self._pipeline_running = False
        self._pipeline_paused = False

    def compose(self):
        """Create child widgets for the orchestrator controls."""
        yield Label("Pipeline Execution", id="controls-label")

        with Horizontal(id="orchestrator-controls"):
            yield Button("▶ Start", variant="success", id="btn-start-pipeline")
            yield Button("⏹ Stop", variant="error", id="btn-stop-pipeline")
            yield Button("⏸ Pause", variant="warning", id="btn-pause-resume")

    def set_pipeline_running(self, running: bool) -> None:
        """Update the pipeline running state.

        Args:
            running: True if a pipeline is currently executing (not paused).
        """
        self._pipeline_running = running
        self._update_pause_button()

    def set_pipeline_paused(self, paused: bool) -> None:
        """Update the pipeline paused state.

        Args:
            paused: True if the pipeline is currently paused.
        """
        self._pipeline_paused = paused
        self._update_pause_button()

    def _update_pause_button(self):
        """Update the pause/resume button text based on current state."""
        try:
            btn = self.query_one("#btn-pause-resume", Button)
            if self._pipeline_running and not self._pipeline_paused:
                btn.update("⏸ Pause")
            elif self._pipeline_paused:
                btn.update("▶ Resume")
            else:
                btn.update("⏸ Pause")
        except Exception:
            pass

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Handle button presses. Dispatches actions to the parent dashboard."""
        btn_id = event.button.id
        if btn_id == "btn-start-pipeline":
            self._on_start()
        elif btn_id == "btn-stop-pipeline":
            self._on_stop()
        elif btn_id == "btn-pause-resume":
            if self._pipeline_paused:
                self._on_resume()
            else:
                self._on_pause()

    def _on_start(self):
        """Handle start pipeline action. Dispatches to parent app."""
        try:
            parent = self.app
            if hasattr(parent, "action_start_pipeline"):
                parent.action_start_pipeline()
        except Exception:
            pass

    def _on_stop(self):
        """Handle stop pipeline action. Dispatches to parent app."""
        try:
            parent = self.app
            if hasattr(parent, "action_stop_pipeline"):
                parent.action_stop_pipeline()
        except Exception:
            pass

    def _on_pause(self):
        """Handle pause pipeline action. Dispatches to parent app."""
        try:
            parent = self.app
            if hasattr(parent, "action_pause_pipeline"):
                parent.action_pause_pipeline()
        except Exception:
            pass

    def _on_resume(self):
        """Handle resume pipeline action. Dispatches to parent app."""
        try:
            parent = self.app
            if hasattr(parent, "action_resume_pipeline"):
                parent.action_resume_pipeline()
        except Exception:
            pass

